"""Verified retained annual raster inputs for the original land-cover ledger.

No raster is resampled, no modeled run is created, and original mask/auxiliary
members must belong to the same immutable source entry.
"""
from __future__ import annotations
import math
from pathlib import Path

from .common import digest, identifier
from .landcover_ledger import LedgerError, RasterInput, _grid_info

SCHEMA = 'upstate.landcover-source-binding/v1'


def source_selection(value):
    if not isinstance(value, dict) or set(value) - {'source_collection_id', 'source_id', 'band'}:
        raise LedgerError('Choose an original source collection, raster source ID and band')
    collection = identifier(value.get('source_collection_id'))
    source_id = value.get('source_id')
    band = value.get('band', 1)
    if not isinstance(source_id, str) or not source_id.strip():
        raise LedgerError('Choose a retained raster source ID')
    if isinstance(band, bool) or not isinstance(band, int) or band < 1:
        raise LedgerError('Raster band must be a positive integer')
    return {'source_collection_id': collection, 'source_id': source_id, 'band': band}


def _scalar(value):
    if value is None:
        return None
    number = float(value)
    return number if math.isfinite(number) else str(number)


def operand(workspace, value, *, allow_projected_area=False):
    import numpy as np
    import rasterio
    selection = source_selection(value)
    path, entry = workspace.source_file(selection['source_collection_id'], selection['source_id'])
    if entry.get('kind') != 'raster':
        raise LedgerError('Choose a retained categorical land-cover raster source')
    path = Path(path)
    # Workspace.source_file is the authority for native member layout and hashes.
    view = workspace.root / 'source-views' / selection['source_collection_id'] / digest(selection['source_id'])
    originals = [entry['body'], *entry.get('companions', [])]
    retained = {(view / row.get('view_path', row['filename'])).resolve(): row for row in originals}
    band = selection['band']
    with rasterio.open(path) as dataset:
        if band > dataset.count:
            raise LedgerError('Selected band is absent from original raster: ' + selection['source_id'])
        dtype = dataset.dtypes[band - 1]
        if not np.issubdtype(np.dtype(dtype), np.integer):
            raise LedgerError('Categorical land cover requires an integer raster band: ' + selection['source_id'])
        grid = _grid_info(dataset, allow_projected_area)
        dependencies = []
        for native_path in dataset.files:
            dependency = Path(native_path).resolve(strict=True)
            if dependency not in retained:
                raise LedgerError('Raster dependency is not a retained source companion: ' + str(native_path))
            descriptor = retained[dependency]
            dependencies.append({'path': dependency.relative_to(view.resolve()).as_posix(),
                                 'bytes': descriptor['bytes'], 'sha256': descriptor['sha256']})
        header = {'grid': grid, 'band_count': dataset.count, 'dtype': dtype,
                  'nodata': _scalar(dataset.nodatavals[band-1]),
                  'mask_flags': [flag.name for flag in dataset.mask_flag_enums[band-1]],
                  'dependencies': sorted(dependencies, key=lambda row: row['path'])}
        native_grid = (dataset.width, dataset.height, dataset.crs, dataset.transform)
    record = {'source_selection': selection, 'source_entry': entry, 'header': header,
              'basis': 'retained_categorical_source',
              'raster': {'path': path.relative_to(workspace.root).as_posix(),
                         'bytes': entry['body']['bytes'], 'sha256': entry['body']['sha256']}}
    return RasterInput(path, band), native_grid, record


def prepare(workspace, selection):
    references = [selection['baseline_source'], *selection['alternative_sources']]
    planar = selection.get('options', {}).get('allow_projected_area', False)
    if not isinstance(planar, bool):
        raise LedgerError('Projected planar area permission must be a boolean')
    operands = [operand(workspace, reference, allow_projected_area=planar) for reference in references]
    if any(item[1] != operands[0][1] for item in operands[1:]):
        raise LedgerError('Original raster sources must have identical width, height, CRS and affine transform; choose aligned retained editions')
    keys = ['source-' + digest(reference)[:20] for reference in references[1:]]
    if len(set(keys)) != len(keys):
        raise LedgerError('Original raster selections have colliding ledger identifiers')
    return operands, keys


def presentation(records, keys):
    def item(record, key):
        entry = record['source_entry']
        selected = record['source_selection']
        return {'key': key, 'label': entry['title'], 'source_time': entry['vintage'],
                'source_collection_id': selected['source_collection_id'],
                'source_id': selected['source_id'], 'band': selected['band'],
                'raster': record['raster'], 'source_crs': record['header']['grid']['crs'],
                'units': 'NLCD categorical class code', 'source_uri': entry['uri']}
    return {'schema': 'upstate.landcover-source-editions/v1', 'input_mode': 'sources',
            'area_method': 'fractional_polygon_overlap', 'binding_file': 'input-editions.json',
            'baseline': item(records[0], 'baseline'),
            'alternatives': [item(record, key) for record, key in zip(records[1:], keys)]}


def same_grid(original, current):
    """Keep original display metadata while checking CRS meaning and the lattice."""
    from pyproj import CRS
    if CRS.from_user_input(original['wkt']) != CRS.from_user_input(current['wkt']):
        return False
    display = {'crs', 'wkt', 'projection_method'}
    return {key: value for key, value in original.items() if key not in display} == {
        key: value for key, value in current.items() if key not in display}


def same_records(originals, current):
    if len(originals) != len(current):
        return False
    for old, new in zip(originals, current):
        if {k: v for k, v in old.items() if k != 'header'} != {
                k: v for k, v in new.items() if k != 'header'}:
            return False
        if {k: v for k, v in old['header'].items() if k != 'grid'} != {
                k: v for k, v in new['header'].items() if k != 'grid'}:
            return False
        if not same_grid(old['header']['grid'], new['header']['grid']):
            return False
    return True

"""Observed multi-year class trajectories inside the original ledger tile transaction.

All areas use the ledger's fractional polygon weights and one common supported
mask across every selected observation. No intervening year is interpolated.
"""
from __future__ import annotations
import json
import math
from pathlib import Path
import zlib

import numpy as np
import rasterio

SCHEMA = "upstate.landcover-timeline/v1"
STATUS = {1: "stable", 2: "changed_once", 3: "changed_multiple", 4: "returned_to_initial"}
RASTERS = {
    "sequence": "timeline-class-sequence.tif",
    "status": "timeline-status.tif",
    "change_count": "timeline-change-count-plus-one.tif",
    "final_observations": "timeline-final-class-observations.tif",
    "last_change_to_year": "timeline-last-transition-to-year.tif",
    "forest_status": "timeline-forest-status.tif",
}


def years(value, count=None):
    from .landcover_ledger import LedgerError
    if (not isinstance(value, (list, tuple)) or len(value) < 2
            or any(type(year) is not int or not 1 <= year <= 9999 for year in value)
            or any(a >= b for a, b in zip(value, value[1:]))
            or count is not None and len(value) != count):
        raise LedgerError("Choose at least two distinct observation years in increasing order, one per retained source band")
    return list(value)


def describe(codes, observation_years):
    """The observed class path, including returns after any previously left class."""
    changed_at = [i for i in range(1, len(codes)) if codes[i] != codes[i - 1]]
    seen = {codes[0]}
    reversals = 0
    for i in changed_at:
        reversals += int(codes[i] in seen)
        seen.add(codes[i])
    last = changed_at[-1] if changed_at else 0
    returned = bool(changed_at and codes[-1] == codes[0])
    status = ("returned_to_initial" if returned else "changed_multiple" if len(changed_at) > 1
              else "changed_once" if changed_at else "stable")
    return {
        "change_count": len(changed_at), "reversal_count": reversals,
        "returned_to_initial": returned,
        "last_change_from_year": observation_years[last - 1] if changed_at else None,
        "last_change_to_year": observation_years[last] if changed_at else None,
        "final_class_observations": len(codes) - last,
        "status": status,
    }


def prepare_tile(values, mask, observation_years):
    """Deduplicate actual cell sequences once; retain the exact common-support mask."""
    matrix = np.stack([value[0][mask] for value in values], axis=1)
    patterns, inverse = np.unique(matrix, axis=0, return_inverse=True)
    details = [describe([int(code) for code in row], observation_years) for row in patterns]
    return {"mask": mask, "patterns": patterns, "inverse": inverse, "details": details}


def tile_delta(prepared, weights, cell_ha):
    selected = weights[prepared["mask"]]
    size = len(prepared["patterns"])
    hectares = np.bincount(prepared["inverse"], weights=selected * cell_ha, minlength=size)
    counts = np.bincount(prepared["inverse"], weights=(selected > 0).astype(np.int64), minlength=size)
    return {"patterns": [[row.tolist(), float(hectares[i]), int(counts[i])]
                         for i, row in enumerate(prepared["patterns"]) if counts[i] > 0]}


def initialize_rasters(output, source, observation_years, resume):
    from .landcover_ledger import LedgerError
    paths = {key: Path(output) / name for key, name in RASTERS.items()}
    for key, path in paths.items():
        count = len(observation_years) if key == "sequence" else 1
        dtype = "uint8" if key in ("sequence", "status", "forest_status") else "uint16"
        if resume:
            if not path.is_file():
                raise LedgerError("Temporal checkpoint raster missing: " + str(path))
            with rasterio.open(path) as retained:
                if (retained.width, retained.height, retained.crs, retained.transform,
                        retained.count, retained.dtypes[0], retained.nodata) != (
                        source.width, source.height, source.crs, source.transform, count, dtype, 0):
                    raise LedgerError("Temporal checkpoint raster grid or encoding changed")
            continue
        with rasterio.open(path, "w", driver="GTiff", width=source.width, height=source.height,
                           count=count, dtype=dtype, crs=source.crs, transform=source.transform,
                           nodata=0, compress="deflate", tiled=True, blockxsize=256, blockysize=256,
                           BIGTIFF="IF_SAFER") as target:
            target.update_tags(ledger_timeline_schema=SCHEMA, selected_years=json.dumps(observation_years))
            if key == "sequence":
                for band, year in enumerate(observation_years, 1):
                    target.set_band_description(band, str(year) + " observed NLCD class; zero excluded")
            else:
                descriptions = {
                    "status": "1 stable; 2 one observed transition; 3 multiple; 4 returned to initial class; 0 excluded",
                    "change_count": "Observed adjacent class transition count plus one; 0 excluded",
                    "final_observations": "Trailing selected observations in the final class; 0 excluded",
                    "last_change_to_year": "Later selected year of last observed transition; 0 stable or excluded (use status)",
                    "forest_status": "1 always forest; 2 always outside forest; 3 ended in forest after entry; 4 ended outside after exit; 5 returned to initial membership; 0 excluded",
                }
                target.set_band_description(1, descriptions[key])
    return paths


def write_rasters(paths, values, prepared, window, shape):
    from .landcover_ledger import GROUPS
    mask = prepared["mask"] if prepared is not None else np.zeros(shape, dtype=bool)
    status_codes = {value: key for key, value in STATUS.items()}
    patterns = prepared["patterns"] if prepared is not None else []
    details = prepared["details"] if prepared is not None else []
    forest = set(GROUPS["forest"])
    forest_codes = []
    for pattern in patterns:
        present = [int(code) in forest for code in pattern]
        if all(present):
            value = 1
        elif not any(present):
            value = 2
        elif present[-1] == present[0]:
            value = 5
        else:
            value = 3 if present[-1] else 4
        forest_codes.append(value)
    # Every raster closes before the caller commits this tile's original SQLite row.
    for key, path in paths.items():
        with rasterio.open(path, "r+") as target:
            if key == "sequence":
                for band in range(1, target.count + 1):
                    data = np.zeros(shape, dtype=np.uint8)
                    if values is not None:
                        data[mask] = values[band - 1][0][mask]
                    target.write(data, band, window=window)
                continue
            data = np.zeros(shape, dtype=target.dtypes[0])
            if prepared is not None and len(patterns):
                if key == "status":
                    lookup = [status_codes[row["status"]] for row in details]
                elif key == "change_count":
                    lookup = [row["change_count"] + 1 for row in details]
                elif key == "final_observations":
                    lookup = [row["final_class_observations"] for row in details]
                elif key == "last_change_to_year":
                    lookup = [row["last_change_to_year"] or 0 for row in details]
                else:
                    lookup = forest_codes
                data[mask] = np.asarray(lookup, dtype=data.dtype)[prepared["inverse"]]
            target.write(data, 1, window=window)


def aggregate(db, report, observation_years):
    from .landcover_ledger import CLASSES, GROUPS, LedgerError
    observation_years = years(observation_years, len(report["scenarios"]) + 1)
    totals = {zone["id"]: {} for zone in report["zones"]}
    for (payload,) in db.execute("SELECT payload FROM tiles ORDER BY tile_id"):
        for delta in json.loads(zlib.decompress(payload)):
            if "temporal" not in delta:
                continue
            accumulator = totals[delta["zone_id"]]
            for codes, area, count in delta["temporal"]["patterns"]:
                key = tuple(codes)
                prior = accumulator.setdefault(key, [0.0, 0])
                prior[0] += area
                prior[1] += count
    support = {row["zone_id"]: row["support"] for row in report["rows"]
               if row["scenario"] == report["scenarios"][0]}
    rows = []
    for zone in report["zones"]:
        analysis = support[zone["id"]]["analysis_valid_ha"]
        covered = support[zone["id"]]["covered_ha"]
        patterns = totals[zone["id"]]
        if not math.isclose(sum(value[0] for value in patterns.values()), analysis, rel_tol=3e-10, abs_tol=1e-8):
            raise LedgerError("Temporal sequence totals differ from the original common-support ledger")
        annual = [{code: 0.0 for code in CLASSES} for year in observation_years]
        adjacent = [{} for year in observation_years[1:]]
        summary = dict.fromkeys((
            "stable_ha", "changed_ha", "one_observed_transition_ha", "multiple_observed_transitions_ha",
            "returned_to_initial_ha", "changed_without_return_ha", "persistent_final_ha",
            "unconfirmed_final_ha", "forest_internal_only_ha", "forest_exit_ha", "forest_entry_ha"), 0.0)
        groups = {name: dict.fromkeys(("stable_present_ha", "stable_absent_ha",
                                      "entered_ha", "exited_ha", "returned_ha"), 0.0) for name in GROUPS}
        trajectories = []
        for codes, (area, count) in sorted(patterns.items()):
            detail = describe(codes, observation_years)
            trajectories.append({"codes": list(codes), "ha": area, "intersecting_cells": count, **detail})
            changes = detail["change_count"]
            summary["changed_ha" if changes else "stable_ha"] += area
            if changes:
                summary["one_observed_transition_ha" if changes == 1 else "multiple_observed_transitions_ha"] += area
                summary["returned_to_initial_ha" if detail["returned_to_initial"] else "changed_without_return_ha"] += area
                summary["persistent_final_ha" if detail["final_class_observations"] >= 2 else "unconfirmed_final_ha"] += area
            for i, code in enumerate(codes):
                annual[i][code] += area
            for i, pair in enumerate(zip(codes, codes[1:])):
                entry = adjacent[i].setdefault(pair, [0.0, 0])
                entry[0] += area
                entry[1] += count
            for name, members in GROUPS.items():
                present = [code in members for code in codes]
                enters = any(not a and b for a, b in zip(present, present[1:]))
                exits = any(a and not b for a, b in zip(present, present[1:]))
                returned = (enters or exits) and present[-1] == present[0]
                if all(present):
                    groups[name]["stable_present_ha"] += area
                if not any(present):
                    groups[name]["stable_absent_ha"] += area
                if enters:
                    groups[name]["entered_ha"] += area
                if exits:
                    groups[name]["exited_ha"] += area
                if returned:
                    groups[name]["returned_ha"] += area
                if name == "forest":
                    if changes and all(present):
                        summary["forest_internal_only_ha"] += area
                    if exits:
                        summary["forest_exit_ha"] += area
                    if enters:
                        summary["forest_entry_ha"] += area
        rows.append({
            "zone_id": zone["id"], "zone_name": zone["name"],
            "analysis_ha": analysis, "covered_ha": covered,
            "coverage_pct": analysis / covered * 100 if covered else None,
            "trajectories": trajectories,
            "annual": [{"year": year, "classes": [{"code": code, "ha": area} for code, area in counts.items()]}
                       for year, counts in zip(observation_years, annual)],
            "adjacent": [{"from_year": a, "to_year": b, "transitions": [
                {"from_code": pair[0], "to_code": pair[1], "ha": values[0], "intersecting_cells": values[1]}
                for pair, values in sorted(counts.items())]}
                         for a, b, counts in zip(observation_years, observation_years[1:], adjacent)],
            "summary": summary if analysis else dict.fromkeys(summary, None),
            "groups": groups if analysis else {name: dict.fromkeys(values, None) for name, values in groups.items()},
        })
    return {
        "schema": SCHEMA, "years": observation_years,
        "intervals": [{"from_year": a, "to_year": b, "gap_years": b - a}
                      for a, b in zip(observation_years, observation_years[1:])],
        "rows": rows,
        "interpretation": [
            "Every annual, adjacent and whole-trajectory total uses the same supported pixels across all selected observations and the original fractional watershed boundaries.",
            "Selected years are observed source labels. An interval brackets a mapped transition; missing years are not interpolated and its event date is not inferred.",
            "Changed area means at least one observed class transition, even when the first and last classes agree. Reversal count counts a return to any previously observed class after leaving it.",
            "Persistent final area means changed cells whose final class appears in at least two trailing selected observations. It describes observed retention, not continuous duration, verified ground change or future permanence.",
            "Entry and exit group areas each count a cell once if that crossing occurred anywhere in its sequence. They overlap for returning paths and must not be added as disjoint categories.",
            "Forest internal-only area changes among 41, 42 and 43 while remaining in that forest group in every selected observation. Woody wetland 90 remains a separate NLCD wetland class.",
            "Two observations support an endpoint transition only. Repeated final-state evidence and observed returns require additional selected observations.",
            "Classification disagreement and source revision can contribute to apparent changes; use consistent product collections, original metadata and confidence/reference products when interpreting real land change.",
            "A cell crossing watershed boundaries has positive-area counts in each intersected zone; use fractional hectares, and use the unique domain for study-wide totals.",
        ],
        "raster_encoding": {
            "sequence": "One band per selected year in the same order; original NLCD code; 0 excluded.",
            "status": STATUS,
            "change_count": "Stored value minus one; 0 excluded.",
            "final_observations": "Number of trailing selected observations equal to the final class; 0 excluded.",
            "last_change_to_year": "Later selected year of last transition; 0 stable or excluded (distinguish with status).",
            "forest_status": {1: "always forest", 2: "always outside forest", 3: "ended in forest after entry",
                              4: "ended outside forest after exit", 5: "returned to initial forest membership"},
        },
    }


def export_csv(root, report):
    """Complete tabular receiving for the same original report and its chronology."""
    from .landcover_exports import _csv
    from .landcover_ledger import LedgerError
    timeline = report.get("timeline")
    if timeline is None:
        return
    selected_years = years(timeline.get("years"), len(report["scenarios"]) + 1)
    if timeline.get("schema") != SCHEMA or report["options"]["support_scope"] != "all":
        raise LedgerError("Retain the complete all-observation timeline")
    if {row["zone_id"] for row in timeline["rows"]} != {zone["id"] for zone in report["zones"]}:
        raise LedgerError("Timeline zone inventory differs from the original ledger")
    summaries, trajectories, annual, adjacent, groups = [], [], [], [], []
    for row in timeline["rows"]:
        key = {"zone_id": row["zone_id"], "zone_name": row["zone_name"]}
        summaries.append({**key, "analysis_ha": row["analysis_ha"], "covered_ha": row["covered_ha"],
                          "coverage_pct": row["coverage_pct"], **row["summary"]})
        for trajectory in row["trajectories"]:
            trajectories.append({**key, "codes_by_selected_year": "|".join(map(str, trajectory["codes"])),
                                 **{name: value for name, value in trajectory.items() if name != "codes"}})
        for observed in row["annual"]:
            for item in observed["classes"]:
                annual.append({**key, "year": observed["year"], **item,
                               "class": report["classes"][str(item["code"])]})
        for interval in row["adjacent"]:
            for item in interval["transitions"]:
                adjacent.append({**key, "from_year": interval["from_year"], "to_year": interval["to_year"],
                                 **item, "from_class": report["classes"][str(item["from_code"])],
                                 "to_class": report["classes"][str(item["to_code"])]})
        for name, item in row["groups"].items():
            groups.append({**key, "group": name, **item})
    prefix = ["zone_id", "zone_name"]
    _csv(root / "timeline-summary.csv", list(summaries[0]), summaries)
    _csv(root / "timeline-trajectories.csv", prefix + [
        "codes_by_selected_year", "ha", "intersecting_cells", "change_count", "reversal_count",
        "returned_to_initial", "last_change_from_year", "last_change_to_year", "final_class_observations", "status"], trajectories)
    _csv(root / "timeline-annual-classes.csv", prefix + ["year", "code", "class", "ha"], annual)
    _csv(root / "timeline-adjacent-transitions.csv", prefix + [
        "from_year", "to_year", "from_code", "from_class", "to_code", "to_class", "ha", "intersecting_cells"], adjacent)
    _csv(root / "timeline-groups.csv", prefix + [
        "group", "stable_present_ha", "stable_absent_ha", "entered_ha", "exited_ha", "returned_ha"], groups)
    editions = report.get("source_editions")
    if editions is not None:
        originals = [editions["baseline"], *editions["alternatives"]]
        observations = [{
            "observation_year": year, "source_label": item["label"], "source_vintage": item.get("source_time") or "",
            "source_collection_id": item["source_collection_id"], "source_id": item["source_id"],
            "band": item["band"], "raster_bytes": item["raster"]["bytes"],
            "raster_sha256": item["raster"]["sha256"], "original_uri": item.get("source_uri") or "",
        } for year, item in zip(selected_years, originals)]
    else:
        inputs = {item["role"]: item for item in report["inputs"]}
        observations = [{
            "observation_year": year, "role": role, "path": inputs[role]["path"],
            "raster_bytes": inputs[role]["bytes"], "raster_sha256": inputs[role]["sha256"],
        } for year, role in zip(selected_years, ["baseline", *["scenario:" + key for key in report["scenarios"]]])]
    _csv(root / "timeline-source-years.csv", list(observations[0]), observations)

"""Land-cover accounting over the original retained Workspace and source readers.

The original scientific queue owns execution. No hydrology call or source/grid
writer is introduced here. Native contracts are documented in LANDCOVER_LEDGER.
"""
from __future__ import annotations
from contextlib import ExitStack
from dataclasses import asdict
import json
from pathlib import Path

from .landcover_ledger import (Options, RasterInput, LedgerError, run_ledger,
                              sha256_file, atomic_json)
from .landcover_exports import export_report, make_portable
from . import landcover_source_inputs

KIND = 'landcover-ledgers'
BINDING_SCHEMA = 'upstate.landcover-binding/v1'
EDITION_SCHEMA = 'upstate.landcover-edition/v1'


def _native():
    # Delayed import leaves the standalone file-level reducer usable independently.
    from .common import digest, held, identifier, verify_file, describe_file, read_json
    return digest, held, identifier, verify_file, describe_file, read_json


def _operand(workspace, run_id):
    digest, held, identifier, verify_file, describe_file, read_json = _native()
    run = workspace.inspect_run(identifier(run_id))
    grid = workspace.get_grid(run['selection']['grid_id'])
    scenario = workspace._get('scenarios', run['selection']['scenario_id'])
    stage = run.get('stages', {}).get('landcover')
    if stage and stage.get('artifact'):
        descriptor = stage['artifact']
        root = workspace.root / 'runs' / run_id
        basis = 'retained_landcover_stage'
    elif scenario.get('kind') == 'landcover':
        raise LedgerError('The selected land-cover edit has no completed raster yet: ' + run_id)
    else:
        descriptor = grid['files']['NLCD']
        root = workspace.root / 'grids' / grid['id']
        basis = 'retained_grid_NLCD'
    path = verify_file(root, descriptor)
    return path, grid, {
        'run_id': run_id, 'selection': run['selection'],
        'scenario': scenario, 'basis': basis,
        'raster': {**descriptor, 'path': path.relative_to(workspace.root).as_posix()},
    }


def catalog(workspace):
    data = workspace.overview()
    scenarios = {r['id']: r for r in data.get('scenarios', [])}
    runs = []
    for row in data.get('runs', []):
        selection = row.get('selection', {})
        scenario = scenarios.get(selection.get('scenario_id'), {})
        ready = scenario.get('kind') != 'landcover' or bool(
            row.get('stages', {}).get('landcover', {}).get('artifact'))
        runs.append({'id': row['id'], 'selection': selection, 'state': row.get('state'),
                     'title': scenario.get('title') or scenario.get('kind') or row['id'],
                     'landcover_ready': ready, 'scenario_kind': scenario.get('kind')})
    vectors, rasters = [], []
    for collection in data.get('sources', []):
        for entry in collection.get('entries', []):
            if entry.get('kind') == 'raster':
                rasters.append({'source_collection_id': collection['id'],
                                'source_id': entry['id'], 'title': entry['title'],
                                'vintage': entry.get('vintage'), 'uri': entry.get('uri'),
                                'role': entry.get('role'), 'body': entry['body']})
            if entry.get('kind') == 'vector':
                vectors.append({'source_collection_id': collection['id'],
                                'source_id': entry['id'], 'title': entry['title'],
                                'layer': entry.get('layer'), 'vintage': entry.get('vintage'),
                                'body': entry['body']})
    return {'schema': 'upstate.landcover-catalog/v1', 'workspace_id': workspace.project['id'],
            'runs': runs, 'vectors': vectors, 'rasters': rasters, 'editions': overview(workspace)}


def _zones(workspace, selection):
    """Preserve the original reader, source CRS, property values and feature IDs."""
    from .spatial_esri import is_esri_source, OriginalEsriFeatures
    path, entry = workspace.source_file(selection['source_collection_id'], selection['source_id'])
    if entry.get('kind') != 'vector':
        raise LedgerError('Choose a retained polygon source for reporting watersheds')
    id_field = selection.get('id_field') or 'huc12'
    name_field = selection.get('name_field') or 'name'
    selected = selection.get('ids')
    if selected is not None and (not isinstance(selected, list) or not selected or
                                any(not isinstance(x, str) for x in selected)):
        raise LedgerError('Selected watershed IDs must be a nonempty list of original strings')
    wanted = None if selected is None else set(selected)
    features, seen = [], set()
    reader_metadata = {}
    with ExitStack() as stack:
        if is_esri_source(path, entry):
            source = OriginalEsriFeatures(path, entry)
            layer = selection.get('layer')
            if layer and layer != source.name:
                raise LedgerError('Choose the original retained Esri layer name')
            crs = source.crs_wkt
            reader_metadata = source.reader_metadata
            rows = iter(source)
        else:
            import fiona
            kwargs = {}
            layer = selection.get('layer') or entry.get('layer')
            if layer:
                kwargs['layer'] = layer
            source = stack.enter_context(fiona.open(path, **kwargs))
            crs = source.crs_wkt or source.crs
            if not crs:
                raise LedgerError('The reporting source must retain its coordinate system')
            rows = iter(source)
        for feature in rows:
            properties = dict(feature['properties'])
            value = properties.get(id_field)
            if value is None or isinstance(value, (dict, list, bool)):
                raise LedgerError('Reporting feature lacks scalar field ' + id_field)
            if 'huc' in id_field.lower() and not isinstance(value, str):
                raise LedgerError('Original HUC identifiers must remain strings')
            zid = str(value)
            if wanted is not None and zid not in wanted:
                continue
            if not zid or zid in seen:
                raise LedgerError('Duplicate or empty original watershed identifier: ' + zid)
            seen.add(zid)
            geometry = feature['geometry']
            if geometry is None:
                raise LedgerError('Selected watershed has no original geometry: ' + zid)
            # Fiona mappings carry tuples; JSON normalization retains coordinates.
            geometry = json.loads(json.dumps(dict(geometry), allow_nan=False))
            retained = {'_landcover_zone_id': zid,
                        '_landcover_zone_name': str(properties.get(name_field) or zid),
                        '_source_properties': properties, '_source_feature_id': str(feature['id'])}
            if hasattr(feature, 'geometry_operations'):
                retained['_original_esri'] = {
                    'feature_index': feature.source_feature_index, 'id_basis': feature.id_basis,
                    'geometry_operations': feature.geometry_operations}
            features.append({'type': 'Feature', 'id': str(feature['id']),
                             'properties': retained, 'geometry': geometry})
        from pyproj import CRS
        crs = CRS.from_user_input(crs).to_wkt()
    if not features or wanted is not None and wanted - seen:
        raise LedgerError('The original reporting source is missing selected watershed IDs')
    return {'type': 'FeatureCollection', 'crs': {'type': 'name', 'properties': {'name': crs}},
            'features': features}, {'selection': selection, 'source_entry': entry,
                                   'reader_metadata': reader_metadata,
                                   'source_collection_id': selection['source_collection_id']}


def _selection(value):
    if not isinstance(value, dict):
        raise LedgerError('Land-cover selection must be a JSON object')
    mode = value.get('input_mode', 'runs')
    if mode not in ('runs', 'sources', 'timeline'):
        raise LedgerError('Choose retained runs, raster sources or an observed timeline')
    if mode == 'timeline':
        from .landcover_temporal import years
        annual = value.get('annual_sources')
        if not isinstance(annual, list) or any(not isinstance(item, dict) for item in annual):
            raise LedgerError('Choose ordered annual source bands and their observation years')
        selected_years = years([item.get('year') for item in annual])
        references = [landcover_source_inputs.source_selection({k: v for k, v in item.items() if k != 'year'}) for item in annual]
        if len({json.dumps(item, sort_keys=True) for item in references}) != len(references):
            raise LedgerError('A retained source band can appear only once in a timeline')
        inputs = {'input_mode': 'timeline', 'annual_sources': [
            {'year': year, **reference} for year, reference in zip(selected_years, references)]}
    elif mode == 'sources':
        baseline = landcover_source_inputs.source_selection(value.get('baseline_source'))
        alternatives = value.get('alternative_sources')
        if not isinstance(alternatives, list) or not alternatives:
            raise LedgerError('Select at least one alternative raster source')
        alternatives = [landcover_source_inputs.source_selection(item) for item in alternatives]
        identities = [json.dumps(item, sort_keys=True) for item in [baseline, *alternatives]]
        if len(set(identities)) != len(identities):
            raise LedgerError('Choose distinct baseline and alternative source bands')
        inputs = {'input_mode': 'sources', 'baseline_source': baseline,
                  'alternative_sources': alternatives}
    else:
        baseline = value.get('baseline_run_id')
        alternatives = value.get('alternative_run_ids')
        if not isinstance(baseline, str) or not baseline or not isinstance(alternatives, list):
            raise LedgerError('Choose an original baseline and original alternative run IDs')
        if not alternatives or any(not isinstance(x, str) or not x for x in alternatives):
            raise LedgerError('Select at least one alternative run')
        if baseline in alternatives or len(set(alternatives)) != len(alternatives):
            raise LedgerError('Choose distinct baseline and alternative run IDs')
        inputs = {'baseline_run_id': baseline, 'alternative_run_ids': alternatives}
    zones = value.get('zones')
    if not isinstance(zones, dict) or not zones.get('source_collection_id') or not zones.get('source_id'):
        raise LedgerError('Choose an original retained reporting source')
    allowed = {'tile_size', 'support_scope', 'unknown_policy', 'allow_overlap', 'allow_projected_area'}
    options = value.get('options', {})
    if not isinstance(options, dict) or set(options) - allowed:
        raise LedgerError('Choose the supported window, common-support, unknown-class and overlap options')
    if mode == 'timeline':
        if options.get('support_scope', 'all') != 'all':
            raise LedgerError('An observed timeline requires common support across every selected year')
        options = {**options, 'support_scope': 'all'}
    if 'allow_projected_area' in options and not isinstance(options['allow_projected_area'], bool):
        raise LedgerError('Projected planar area permission must be a boolean')
    # The legacy run selection keeps its exact pre-existing shape and identity.
    return {**inputs, 'zones': zones, 'title': str(value.get('title') or 'Land-cover change ledger'),
            'options': options}


def _inputs(workspace, selection):
    if selection.get('input_mode') in ('sources', 'timeline'):
        source_selection = selection
        if selection.get('input_mode') == 'timeline':
            references = [{k: v for k, v in item.items() if k != 'year'} for item in selection['annual_sources']]
            source_selection = {**selection, 'baseline_source': references[0], 'alternative_sources': references[1:]}
        operands, keys = landcover_source_inputs.prepare(workspace, source_selection)
        return {'rasters': [item[0] for item in operands],
                'operands': [item[2] for item in operands], 'keys': keys,
                'schema': landcover_source_inputs.SCHEMA, 'grid_id': None,
                'grid_definition': operands[0][2]['header']['grid'],
                'grid_spec': {'input_mode': selection['input_mode'], 'resampling': 'none'}}
    operands = [_operand(workspace, rid) for rid in
                [selection['baseline_run_id'], *selection['alternative_run_ids']]]
    grid = operands[0][1]
    if any(item[1]['id'] != grid['id'] for item in operands[1:]):
        raise LedgerError('Land-cover comparisons require the same original retained grid ID')
    return {'rasters': [RasterInput(item[0]) for item in operands],
            'operands': [item[2] for item in operands],
            'keys': [item[2]['run_id'] for item in operands[1:]],
            'schema': BINDING_SCHEMA, 'grid_id': grid['id'],
            'grid_definition': grid['grid'], 'grid_spec': grid['spec']}


def preview_inputs(workspace, value):
    """Verify selected native sources and original reporting IDs without a model run."""
    selection = _selection(value)
    inputs = _inputs(workspace, selection)
    zones, zone_binding = _zones(workspace, selection['zones'])
    result = {'schema': 'upstate.landcover-input-preview/v1',
              'input_mode': selection.get('input_mode', 'runs'), 'selection': selection,
              'grid_id': inputs['grid_id'], 'grid': inputs['grid_definition'],
              'reporting': {'feature_count': len(zones['features']),
                            'source_crs': zones['crs']['properties']['name'],
                            'selection': zone_binding['selection'],
                            'source_entry': zone_binding['source_entry']},
              'checked': ['original source bytes and companions', 'integer bands and common native lattice; NLCD class values checked during build',
                          'original reporting source and selected identifiers'],
              'remaining': 'Build computes polygon intersections, valid-data coverage and class transitions.'}
    if selection.get('input_mode') in ('sources', 'timeline'):
        result['source_editions'] = landcover_source_inputs.presentation(inputs['operands'], inputs['keys'])
        result['headers'] = [item['header'] for item in inputs['operands']]
    if selection.get('input_mode') == 'timeline':
        from .landcover_temporal import SCHEMA as TIMELINE_SCHEMA
        selected_years = [item['year'] for item in selection['annual_sources']]
        result['timeline'] = {'schema': TIMELINE_SCHEMA, 'years': selected_years,
                              'intervals': [{'from_year': a, 'to_year': b, 'gap_years': b-a}
                                            for a, b in zip(selected_years, selected_years[1:])]}
        result['remaining'] = 'Build computes the original polygon fractions, all-year common support, annual class paths and observed returns.'
    return result


def build(workspace, value, *, progress=None):
    digest, held, identifier, verify_file, describe_file, read_json = _native()
    selection = _selection(value)
    inputs = _inputs(workspace, selection)
    zones, zone_binding = _zones(workspace, selection['zones'])
    binding = {'schema': inputs['schema'], 'workspace_id': workspace.project['id'],
               'selection': selection, 'grid_id': inputs['grid_id'],
               'grid_definition': inputs['grid_definition'], 'grid_spec': inputs['grid_spec'],
               'operands': inputs['operands'], 'zones': zone_binding,
               'reducer_sha256': sha256_file(Path(__file__).with_name('landcover_ledger.py')),
               'adapter_sha256': sha256_file(__file__)}
    if selection.get('input_mode') in ('sources', 'timeline'):
        binding['source_adapter_sha256'] = sha256_file(landcover_source_inputs.__file__)
    if selection.get('input_mode') == 'timeline':
        binding['temporal_reducer_sha256'] = sha256_file(Path(__file__).with_name('landcover_temporal.py'))
    key = digest(binding)
    parent = workspace.root / KIND
    parent.mkdir(exist_ok=True)
    directory = parent / key
    with held(parent / ('.' + key + '.lock'), blocking=False):
        directory.mkdir(exist_ok=True)
        edition_path = directory / 'edition.json'
        if edition_path.exists():
            return inspect(workspace, key)['edition']
        pending_binding = directory / 'input-bindings.json'
        if pending_binding.exists() and read_json(pending_binding) != binding:
            raise LedgerError('Retained land-cover input selection changed')
        if not pending_binding.exists():
            atomic_json(pending_binding, binding)
        zone_path = directory / 'zones-original.geojson'
        if zone_path.exists() and read_json(zone_path) != zones:
            raise LedgerError('Retained land-cover reporting geometry changed')
        if not zone_path.exists():
            atomic_json(zone_path, zones)
        output = directory / 'results'
        options = Options(**selection['options'], title=selection['title'],
                          resume=(output / 'ledger.sqlite3').exists())
        # All original operands have already been verified by common.verify_file.
        report = run_ledger(inputs['rasters'][0],
                            dict(zip(inputs['keys'], inputs['rasters'][1:])),
                            zone_path, output, options=options,
                            id_field='_landcover_zone_id', name_field='_landcover_zone_name',
                            context_files=[pending_binding], progress=progress,
                            temporal_years=([item['year'] for item in selection['annual_sources']]
                                            if selection.get('input_mode') == 'timeline' else None))
        if selection.get('input_mode') in ('sources', 'timeline'):
            report['source_editions'] = landcover_source_inputs.presentation(inputs['operands'], inputs['keys'])
            atomic_json(output / 'input-editions.json', binding)
            atomic_json(output / 'ledger.json', report)
        export_report(output)
        archive = directory / 'landcover-report.zip'
        if not archive.exists():
            make_portable(output, archive)
        files = {p.name: describe_file(directory, p) for p in output.iterdir()
                 if p.is_file() and p.suffix in ('.json', '.geojson', '.csv', '.html', '.tif')
                 and p.name != 'status.json'}
        files['archive'] = describe_file(directory, archive)
        files['binding'] = describe_file(directory, pending_binding)
        files['original_zones'] = describe_file(directory, zone_path)
        edition = {'schema': EDITION_SCHEMA, 'id': key, 'title': selection['title'],
                   'workspace_id': workspace.project['id'], 'grid_id': inputs['grid_id'],
                   'selection': selection, 'binding_sha256': digest(binding),
                   'signature': report['signature'], 'zone_count': len(zones['features']),
                   'alternative_count': len(inputs['operands'])-1, 'files': files, 'state': 'complete'}
        atomic_json(edition_path, edition)
        return edition


def inspect(workspace, key):
    digest, held, identifier, verify_file, describe_file, read_json = _native()
    directory = workspace.root / KIND / identifier(key)
    edition = read_json(directory / 'edition.json')
    if edition.get('schema') != EDITION_SCHEMA or edition.get('id') != key:
        raise LedgerError('Land-cover edition identity differs')
    binding = read_json(verify_file(directory, edition['files']['binding']))
    if binding['workspace_id'] != workspace.project['id'] or digest(binding) != key:
        raise LedgerError('Land-cover edition belongs to a different source selection')
    if edition.get('selection') != binding['selection'] or edition.get('grid_id') != binding['grid_id'] or edition.get('binding_sha256') != key:
        raise LedgerError('Land-cover edition selection differs from its retained binding')
    source_mode = binding.get('schema') == landcover_source_inputs.SCHEMA
    if source_mode:
        if binding['selection'].get('input_mode') not in ('sources', 'timeline'):
            raise LedgerError('Source binding mode differs from its retained selection')
        current = _inputs(workspace, binding['selection'])
        if (not landcover_source_inputs.same_records(binding['operands'], current['operands'])
                or current['grid_id'] != binding['grid_id']
                or not landcover_source_inputs.same_grid(binding['grid_definition'], current['grid_definition'])
                or current['grid_spec'] != binding['grid_spec']):
            raise LedgerError('Original land-cover source edition or native header changed')
    elif binding.get('schema') == BINDING_SCHEMA:
        grid = workspace.get_grid(binding['grid_id'])
        if grid['grid'] != binding['grid_definition'] or grid['spec'] != binding['grid_spec']:
            raise LedgerError('Original land-cover grid changed')
    else:
        raise LedgerError('Unknown retained land-cover binding schema')
    source_selection = binding['zones']['selection']
    _, source_entry = workspace.source_file(source_selection['source_collection_id'], source_selection['source_id'])
    if source_entry != binding['zones']['source_entry']:
        raise LedgerError('Original reporting source changed')
    for descriptor in edition['files'].values():
        verify_file(directory, descriptor)
    if not source_mode:
        for operand in binding['operands']:
            original = workspace.inspect_run(operand['run_id'])
            if original['selection'] != operand['selection']:
                raise LedgerError('Original selected run changed')
            verify_file(workspace.root, operand['raster'])
    report = read_json(verify_file(directory, edition['files']['ledger.json']))
    if report.get('signature') != edition['signature']:
        raise LedgerError('Land-cover report differs from its native edition')
    if source_mode:
        if read_json(verify_file(directory, edition['files']['input-editions.json'])) != binding:
            raise LedgerError('Portable source binding differs from the original edition')
        if report.get('source_editions') != landcover_source_inputs.presentation(binding['operands'], current['keys']):
            raise LedgerError('Source chronology differs from the original edition')
    if binding['selection'].get('input_mode') == 'timeline':
        from .landcover_temporal import SCHEMA as TIMELINE_SCHEMA
        selected_years = [item['year'] for item in binding['selection']['annual_sources']]
        if (report.get('timeline', {}).get('schema') != TIMELINE_SCHEMA
                or report['timeline'].get('years') != selected_years
                or report['options']['support_scope'] != 'all'):
            raise LedgerError('Observed chronology differs from the retained annual selection')
    return {'edition': edition, 'binding': binding, 'report': report}


def overview(workspace):
    digest, held, identifier, verify_file, describe_file, read_json = _native()
    result = []
    for path in sorted((workspace.root / KIND).glob('*/edition.json')):
        row = read_json(path)
        if row.get('schema') != EDITION_SCHEMA or row.get('id') != path.parent.name:
            raise LedgerError('Land-cover edition metadata differs')
        result.append({key: row[key] for key in ('id', 'title', 'state', 'grid_id',
                                                'zone_count', 'alternative_count', 'selection')})
    return result


def verify_all(workspace):
    return [{'id': row['id'], 'signature': inspect(workspace, row['id'])['edition']['signature']}
            for row in overview(workspace)]

